import { render } from '@solidjs/web';
import Steps from './steps';
import './styles.css';

function App() {
  return (
    <Steps>
      <p>Pick a product</p>
      <p>Add it to your cart</p>
      <p>Check out</p>
    </Steps>
  );
}

render(() => <App />, document.getElementById('app'));

import { children, For } from 'solid-js';

export default function Steps(props) {
  return <div class="steps">{props.children}</div>;
}

.steps li {
  margin: 0.5rem 0;
  padding: 0.25rem 0.75rem;
  border-left: 4px solid #446b9e;
  list-style: none;
}

.steps li p {
  margin: 0;
}

import { render } from '@solidjs/web';
import Steps from './steps';
import './styles.css';

function App() {
  return (
    <Steps>
      <p>Pick a product</p>
      <p>Add it to your cart</p>
      <p>Check out</p>
    </Steps>
  );
}

render(() => <App />, document.getElementById('app'));

import { children, For } from 'solid-js';

export default function Steps(props) {
  const steps = children(() => props.children);

  return (
    <ol class="steps">
      <For each={steps.toArray()}>
        {(step, index) => (
          <li>
            <strong>Step {index() + 1}</strong>
            {step}
          </li>
        )}
      </For>
    </ol>
  );
}

.steps li {
  margin: 0.5rem 0;
  padding: 0.25rem 0.75rem;
  border-left: 4px solid #446b9e;
  list-style: none;
}

.steps li p {
  margin: 0;
}
